const { randomUUID } = require('crypto');
const request = $input.first().json;
if (request.skip === true) return [{ json: { skip: true } }];

const context = request.context ?? {};
if (context.execution_mode !== 'OFFLINE_EVAL' || context.external_effects_allowed !== false) {
  throw new Error('Gerente simulado aceita somente OFFLINE_EVAL');
}

const receivedAt = context.received_at || new Date().toISOString();
const evidenceSource = {
  source_id: 'offline_eval_webhook',
  source_type: 'SYNTHETIC_INPUT',
  source_version: '1.0.0',
  source_status: 'ACTIVE',
  artifact_hash: context.input_hash,
  lineage_node_id: `input-${context.event_id}`,
  captured_at: receivedAt,
  observed_at: receivedAt,
  recorded_at: receivedAt,
  valid_from: receivedAt,
  valid_to: null,
  period_start: null,
  period_end: null,
  freshness_status: 'CURRENT',
  precedence_rule_id: 'offline.synthetic.v1',
  locator: `event://${context.event_id}`
