        requires_manual_review: false,
        remediation: 'Conectar fontes cadastrais oficiais após homologação em produção.'
      }
    ],
    recommended_actions: [
      {
        action_id: `act-conta-${randomUUID().slice(0, 8)}`,
        action: 'Manter cadastro ativo e programar atualização cadastral periódica.',
        target_system: 'CADASTRO_CORE',
        priority: 'P2',
        prerequisites: [],
        requires_human_approval: false,
        execution_authorization: 'NOT_APPLICABLE',
        related_finding_ids: ['identidade_e_cadastro']
      }
    ],
    warnings: ['OFFLINE_EVAL: resultado sintético validado para conformidade e elegibilidade.']
  }),

  performance: (ctx) => ({
    manager: 'GERENTE_GERAL_PERFORMANCE',
    overall_assessment: {
      evidence_quality: 'SUFFICIENT',
      data_completeness: 'COMPLETE',
      eligibility: 'NOT_APPLICABLE',
      risk_level: 'MEDIUM',
      decision_status: 'READY'
    },
    findings: [
      {
        finding_id: `perf-producao-${randomUUID().slice(0, 8)}`,
        topic: 'producao_comercial_vs_meta',
        statement: 'Produção realizada de R$ 28.000,00 frente à meta mensal de R$ 35.000,00, atingindo 80,0% do objetivo da competência.',
        inference_type: 'DETERMINISTIC',
