        target_system: 'ESTEIRA_COMERCIAL',
        priority: 'P1',
        prerequisites: [],
        requires_human_approval: false,
        execution_authorization: 'NOT_APPLICABLE',
        related_finding_ids: ['gap_execucao_competencia']
      }
    ],
    warnings: ['OFFLINE_EVAL: cálculo determinístico de atingimento e gap de performance.']
  }),

  financeiro: (ctx) => ({
    manager: 'GERENTE_GERAL_FINANCEIRO',
    overall_assessment: {
      evidence_quality: 'SUFFICIENT',
