        model_confidence: null,
        calibration_profile_id: null,
        evidence_quality: 'SUFFICIENT',
        risk_level: 'LOW',
        evidence_sources: [evidenceSource]
      },
      {
        finding_id: `fin-viabilidade-${randomUUID().slice(0, 8)}`,
        topic: 'viabilidade_economica',
        statement: 'Viabilidade econômica favorável para oferta de pacote de serviços e otimização de tarifas de cobrança/pagamentos, gerando maior retorno da carteira.',
        inference_type: 'DETERMINISTIC',
        model_confidence: null,
