        action: 'Elaborar proposta de otimização de tarifas e centralização de fluxo de caixa para maximizar margem bancária.',
        target_system: 'SISTEMA_TARIFAS',
        priority: 'P2',
        prerequisites: [],
        requires_human_approval: false,
        execution_authorization: 'NOT_APPLICABLE',
        related_finding_ids: ['viabilidade_economica']
      }
    ],
    warnings: ['OFFLINE_EVAL: faturamento e rentabilidade analisados em base sintética.']
  }),

  relacionamento: (ctx) => ({
    manager: 'GERENTE_GERAL_RELACIONAMENTO',
    overall_assessment: {
      evidence_quality: 'SUFFICIENT',
      data_completeness: 'COMPLETE',
      eligibility: 'NOT_APPLICABLE',
      risk_level: 'LOW',
      decision_status: 'READY'
    },
    findings: [
      {
        finding_id: `rel-historico-${randomUUID().slice(0, 8)}`,
