        inference_type: 'DETERMINISTIC',
        model_confidence: null,
        calibration_profile_id: null,
        evidence_quality: 'SUFFICIENT',
        risk_level: 'LOW',
        evidence_sources: [evidenceSource]
      },
      {
        finding_id: `rel-compromissos-${randomUUID().slice(0, 8)}`,
        topic: 'compromissos_e_proximos_passos',
        statement: 'Reunião de alinhamento e retorno agendada para 05/09/2026. Necessidade de apresentação de proposta consultiva customizada de eficiência.',
        inference_type: 'DETERMINISTIC',
        model_confidence: null,
        calibration_profile_id: null,
        evidence_quality: 'SUFFICIENT',
        risk_level: 'LOW',
        evidence_sources: [evidenceSource]
      }
    ],
    gates: [],
    data_gaps: [],
    recommended_actions: [
      {
        action_id: `act-rel-${randomUUID().slice(0, 8)}`,
        action: 'Preparar material executivo para a reunião de retorno agendada em 05/09/2026, destacando ganhos de eficiência e metas compartilhadas.',
        target_system: 'AGENDA_RELACIONAMENTO',
        priority: 'P1',
        prerequisites: [],
        requires_human_approval: true,
        execution_authorization: 'PENDING_HUMAN',
        related_finding_ids: ['compromissos_e_proximos_passos']
      }
    ],
    warnings: ['OFFLINE_EVAL: histórico e compromissos estruturados para ancoragem executiva.']
  })
};

const builder = domainBuilders[request.domain];
if (!builder) throw new Error('Domínio não autorizado para o Gerente Geral');

const domainData = builder(context);
const capabilities = [...new Set(request.capabilities ?? [])];
if (!capabilities.length || capabilities.length > 3) {
  throw new Error('Capacidade ausente ou acima do limite no domínio');
}

const handoff = {
  schema_version: '3.0.0',
  message_id: randomUUID(),
  trace_id: context.trace_id,
  causation_id: context.routing_id,
  agent_id: domainData.manager,
  agent_role: 'GENERAL_MANAGER',
  producer_version: '2.0.0',
  parent_agent_id: 'DIRETOR_360',
  handoff_level: 'MANAGER_TO_CONSOLIDATION',
  handoff_target: 'MOTOR_CONSOLIDACAO_360',
  domain: request.domain,
  run_id: context.run_id,
  correlation_id: context.correlation_id,
  generated_at: new Date().toISOString(),
  input_snapshot_at: receivedAt,
  input_hash: context.input_hash,
  policy_snapshot: {
    routing: '1.0.0',
    freshness: '1.0.0',
    reason_codes: '1.0.0',
    capability_registry: '2.0.0'
  },
  execution_status: 'SUCCESS',
  overall_assessment: domainData.overall_assessment,
  findings: domainData.findings,
  data_gaps: domainData.data_gaps,
  gates: domainData.gates,
  recommended_actions: domainData.recommended_actions,
  warnings: domainData.warnings
};

const required = [
  'schema_version', 'message_id', 'trace_id', 'agent_id', 'agent_role',
  'handoff_level', 'handoff_target', 'domain', 'run_id', 'correlation_id',
  'input_hash', 'overall_assessment', 'findings', 'data_gaps', 'gates',
  'recommended_actions', 'warnings'
];
if (required.some((field) => handoff[field] === undefined || handoff[field] === null)) {
  throw new Error(`Handoff inválido na fronteira do domínio ${request.domain}`);
}

return [{
  json: {
    domain: request.domain,
    capabilities_executed: capabilities,
    manager_implementation: `${domainData.manager}@2.0.0`,
    domain_handoff: handoff
  }
}];
